# find stop-free stretches by walking from each stop to the next.
def stopfree_spans(s, strand):
    res=[]
    for f0 in range(3):
        # positions (1-based on this strand) of in-frame stops
        pos=[]
        p=f0+1
        while p <= len(s)-2:
            c = s[p-1:p+2]
            if c in stops: pos.append(p)
            p += 3
        # spans between consecutive stops
        prev_end = 0           # last nt covered by a stop codon (1-based); a stop codon uses p-.. p+2
        bounds = [(pp, pp+2) for pp in pos] + [(None,None)]
        cur_start = 1
        for (st,stend) in bounds:
            free_end = st-1 if st is not None else len(s)
            span = free_end-cur_start+1
            if span >= 240:
                res.append((span, f0+1, cur_start, free_end))
            cur_start = (stend+1) if st is not None else None
