def runs(hits, maxlen, maxjitter=2, minrun=3):
    # group seed hits by diagonal (i-j) allowing small jitter
    from collections import defaultdict
    bydiag = defaultdict(list)
    for i,j in hits: bydiag[i-j].append((i,j))
    best=[]
    for d, pts in bydiag.items():
        pts.sort()
        chain=[pts[0]]; 
        for p in pts[1:]:
            if p[0]-chain[-1][0] <= maxjitter+1 and p[1]-chain[-1][1] <= maxjitter+1:
                chain.append(p)
            elif p[0]-chain[-1][0] > 3:
                if len(chain)>=minrun: best.append(chain)
                chain=[p]
            else:
                chain=[p]
        if len(chain)>=minrun: best.append(chain)
    return best

